//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::repr::needs_app_paren, int::write_decimal`; the
//! native twin is `benches/native/Bench/ReprNeedsAppParen.lean`.
//! NOT COMPARABLE: Repr.addAppParen builds a Format (a tree the program renders later); the crate
//! only answers its test

#![allow(unused_parens, unused_imports, unused_variables, unused_mut)]
#![allow(
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]
#![allow(clippy::identity_op, clippy::let_and_return)]

use lean_runtime::semantics::{int, repr};
use lean_runtime_bench::*;
use std::hint::black_box;

#[inline(never)]
fn kernel(inp: &(), n: u64) -> u64 {
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = mix(acc, {
            let i = int_arg(int_box(((x >> 34) as i64) - (1 << 29)));
            let mut b = StackBuf::new();
            let _ = int::write_decimal(&i, &mut b);
            b.as_bytes().len() as u64
                + 2 * repr::needs_app_paren(i.is_neg(), (x >> 4) & 2047) as u64
        });
    }
    acc
}

fn main() {
    run(|| (), kernel)
}
